#!/usr/bin/env python3
"""Stage M52: Core lowering for one read-write memory asm operand plus one scalar input.

The semantic Core shape supports an optional scalar register output. This covers the
RISC-V atomic forms currently exposed by Linux without baking Linux helper names into
Core:
  - test_and_set_bit: =r result, +A memory, r input
  - arch_atomic_add: +A memory, r input
"""

from pathlib import Path

FILES = {
    "ir_h": Path("src/core/core_ir.h"),
    "ir_c": Path("src/core/core_ir.c"),
    "lower": Path("src/core/core_lower.c"),
    "codegen": Path("src/target/riscv64/core_codegen.c"),
}
MARKER = "MINIC_CORE_INSTRUCTION_MEMORY_READWRITE_SCALAR_INPUT_INLINE_ASM"


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected exactly one anchor, found {count}")
    return text.replace(old, new, 1)


def main() -> int:
    texts = {name: path.read_text() for name, path in FILES.items()}
    state = {name: MARKER in text for name, text in texts.items()}
    if all(state.values()):
        print("M52 memory read-write scalar-input inline asm already applied")
        return 0
    if any(state.values()):
        raise SystemExit(f"partial M52 state: {state}")

    texts["ir_h"] = replace_once(
        texts["ir_h"],
        """    MINIC_CORE_INSTRUCTION_REGISTER_OUTPUT_INPUT_INLINE_ASM,\n    MINIC_CORE_INSTRUCTION_SCALAR_INPUT_INLINE_ASM,\n""",
        """    MINIC_CORE_INSTRUCTION_REGISTER_OUTPUT_INPUT_INLINE_ASM,\n    MINIC_CORE_INSTRUCTION_MEMORY_READWRITE_SCALAR_INPUT_INLINE_ASM,\n    MINIC_CORE_INSTRUCTION_SCALAR_INPUT_INLINE_ASM,\n""",
        "core_ir.h instruction kind",
    )
    texts["ir_h"] = replace_once(
        texts["ir_h"],
        """        struct {\n            MinicCoreInlineAsmId inline_asm_id;\n            MinicCoreValueId operand;\n        } register_output_input_inline_asm;\n        struct {\n            MinicCoreInlineAsmId inline_asm_id;\n            MinicCoreValueId operand;\n        } scalar_input_inline_asm;\n""",
        """        struct {\n            MinicCoreInlineAsmId inline_asm_id;\n            MinicCoreValueId operand;\n        } register_output_input_inline_asm;\n        struct {\n            MinicCoreInlineAsmId inline_asm_id;\n            MinicCoreValueId memory_address;\n            MinicCoreValueId operand;\n            size_t memory_operand_index;\n            size_t register_output_operand_index;\n            size_t scalar_input_operand_index;\n        } memory_readwrite_scalar_input_inline_asm;\n        struct {\n            MinicCoreInlineAsmId inline_asm_id;\n            MinicCoreValueId operand;\n        } scalar_input_inline_asm;\n""",
        "core_ir.h payload",
    )

    verify_anchor = """    case MINIC_CORE_INSTRUCTION_SCALAR_INPUT_INLINE_ASM: {\n        const MinicCoreInlineAsm *inline_asm;\n        MinicCoreValueId operand;\n"""
    verify_case = """    case MINIC_CORE_INSTRUCTION_MEMORY_READWRITE_SCALAR_INPUT_INLINE_ASM: {\n        const MinicCoreInlineAsm *inline_asm;\n        MinicCoreValueId memory_address;\n        MinicCoreValueId operand;\n        MinicType pointee;\n        size_t memory_index;\n        size_t register_index;\n        size_t scalar_index;\n        bool has_register_output;\n\n        memory_address = instruction->value.memory_readwrite_scalar_input_inline_asm.memory_address;\n        operand = instruction->value.memory_readwrite_scalar_input_inline_asm.operand;\n        memory_index = instruction->value.memory_readwrite_scalar_input_inline_asm.memory_operand_index;\n        register_index =\n            instruction->value.memory_readwrite_scalar_input_inline_asm.register_output_operand_index;\n        scalar_index =\n            instruction->value.memory_readwrite_scalar_input_inline_asm.scalar_input_operand_index;\n        has_register_output = register_index != SIZE_MAX;\n        if (memory_address >= function->value_count || operand >= function->value_count ||\n            !available_values[memory_address] || !available_values[operand] ||\n            !minic_type_pointee(function->values[memory_address].type, &pointee) ||\n            (!minic_type_is_integer(pointee) && !minic_type_is_pointer(pointee)) ||\n            (!minic_type_is_integer(function->values[operand].type) &&\n             !minic_type_is_pointer(function->values[operand].type)) ||\n            memory_index > 9U || scalar_index > 9U || memory_index == scalar_index ||\n            (has_register_output &&\n             (register_index > 9U || register_index == memory_index || register_index == scalar_index)) ||\n            instruction->value.memory_readwrite_scalar_input_inline_asm.inline_asm_id >=\n                function->inline_asm_count) {\n            return false;\n        }\n        if (has_register_output) {\n            if (!instruction_result_is_valid(function, instruction) ||\n                (!minic_type_is_integer(instruction->type) &&\n                 !minic_type_is_pointer(instruction->type))) {\n                return false;\n            }\n        } else if (instruction->result != MINIC_CORE_VALUE_INVALID ||\n                   !minic_type_is_void(instruction->type)) {\n            return false;\n        }\n        inline_asm = &function->inline_asms[\n            instruction->value.memory_readwrite_scalar_input_inline_asm.inline_asm_id];\n        return inline_asm->template_text != NULL && inline_asm->template_length != 0U &&\n               inline_asm->is_volatile && inline_asm->has_memory_clobber;\n    }\n"""
    texts["ir_c"] = replace_once(
        texts["ir_c"], verify_anchor, verify_case + verify_anchor, "core_ir.c verifier"
    )

    dump_anchor = """    case MINIC_CORE_INSTRUCTION_SCALAR_INPUT_INLINE_ASM: {\n        const MinicCoreInlineAsm *inline_asm;\n        MinicCoreInlineAsmId inline_asm_id;\n"""
    dump_case = """    case MINIC_CORE_INSTRUCTION_MEMORY_READWRITE_SCALAR_INPUT_INLINE_ASM: {\n        const MinicCoreInlineAsm *inline_asm;\n        MinicCoreInlineAsmId inline_asm_id;\n        size_t register_index;\n\n        inline_asm_id = instruction->value.memory_readwrite_scalar_input_inline_asm.inline_asm_id;\n        register_index =\n            instruction->value.memory_readwrite_scalar_input_inline_asm.register_output_operand_index;\n        if (function == NULL || inline_asm_id >= function->inline_asm_count) {\n            return false;\n        }\n        inline_asm = &function->inline_asms[inline_asm_id];\n        if (register_index == SIZE_MAX) {\n            return fprintf(output,\n                           \"  asm.memory_rw_input id=%\" PRIu32 \" mem=%%%\" PRIu32\n                           \" input=%%%\" PRIu32 \" operands=%zu,-,%zu%s%s\\n\",\n                           inline_asm_id,\n                           instruction->value.memory_readwrite_scalar_input_inline_asm.memory_address,\n                           instruction->value.memory_readwrite_scalar_input_inline_asm.operand,\n                           instruction->value.memory_readwrite_scalar_input_inline_asm.memory_operand_index,\n                           instruction->value.memory_readwrite_scalar_input_inline_asm.scalar_input_operand_index,\n                           inline_asm->is_volatile ? \" volatile\" : \"\",\n                           inline_asm->has_memory_clobber ? \" memory\" : \"\") >= 0;\n        }\n        return fprintf(output,\n                       \"  %%%\" PRIu32 \" = asm.memory_rw_input id=%\" PRIu32\n                       \" mem=%%%\" PRIu32 \" input=%%%\" PRIu32 \" operands=%zu,%zu,%zu%s%s\\n\",\n                       instruction->result,\n                       inline_asm_id,\n                       instruction->value.memory_readwrite_scalar_input_inline_asm.memory_address,\n                       instruction->value.memory_readwrite_scalar_input_inline_asm.operand,\n                       instruction->value.memory_readwrite_scalar_input_inline_asm.memory_operand_index,\n                       register_index,\n                       instruction->value.memory_readwrite_scalar_input_inline_asm.scalar_input_operand_index,\n                       inline_asm->is_volatile ? \" volatile\" : \"\",\n                       inline_asm->has_memory_clobber ? \" memory\" : \"\") >= 0;\n    }\n"""
    texts["ir_c"] = replace_once(
        texts["ir_c"], dump_anchor, dump_case + dump_anchor, "core_ir.c dump"
    )

    lower_helper_anchor = """static MinicCoreLowerStatus lower_opaque_inline_asm(MinicCoreLowerContext *context,\n                                                    const MinicStatement *statement) {\n"""
    lower_helpers = """static bool core_inline_asm_constraint_is(const MinicInlineAsmOperand *operand,\n                                              const char *text) {\n    size_t length;\n\n    if (operand == NULL || text == NULL || operand->constraint_text == NULL) {\n        return false;\n    }\n    length = strlen(text);\n    return operand->constraint_length == length &&\n           memcmp(operand->constraint_text, text, length) == 0;\n}\n\nstatic bool core_inline_asm_register_output_constraint(const MinicInlineAsmOperand *operand) {\n    return core_inline_asm_constraint_is(operand, \"=r\") ||\n           core_inline_asm_constraint_is(operand, \"=&r\");\n}\n\n"""
    texts["lower"] = replace_once(
        texts["lower"],
        lower_helper_anchor,
        lower_helpers + lower_helper_anchor,
        "core_lower.c helper anchor",
    )

    lower_anchor = """    if (source->is_volatile && !source->is_goto && source->template_text != NULL &&\n        source->template_length != 0U && source->outputs != NULL && source->inputs != NULL &&\n        source->output_count == 1U && source->input_count == 1U &&\n"""
    lower_cases = """    if (source->is_volatile && !source->is_goto && source->template_text != NULL &&\n        source->template_length != 0U && source->outputs != NULL && source->inputs != NULL &&\n        source->output_count == 2U && source->input_count == 1U && source->has_memory_clobber &&\n        source->label_count == 0U && source->register_clobber_count == 0U &&\n        source->clobber_count == 1U) {\n        const MinicInlineAsmOperand *input;\n        const MinicInlineAsmOperand *memory_output;\n        const MinicInlineAsmOperand *register_output;\n        const MinicExpression *input_expression;\n        const MinicExpression *memory_expression;\n        const MinicExpression *register_expression;\n        const MinicLocal *register_local;\n        MinicCoreValueId input_value;\n        MinicCoreValueId memory_address;\n        MinicCoreValueId output_address;\n        MinicCoreValueId output_value;\n        MinicCoreLowerStatus status;\n        MinicType input_type;\n        MinicType memory_type;\n        MinicType output_type;\n        size_t memory_index;\n        size_t register_index;\n\n        input = &source->inputs[0];\n        memory_output = NULL;\n        register_output = NULL;\n        memory_index = SIZE_MAX;\n        register_index = SIZE_MAX;\n        for (size_t output_index = 0U; output_index < 2U; ++output_index) {\n            const MinicInlineAsmOperand *candidate;\n\n            candidate = &source->outputs[output_index];\n            if (candidate->access == MINIC_INLINE_ASM_OPERAND_READ_WRITE &&\n                core_inline_asm_constraint_is(candidate, \"+A\")) {\n                if (memory_output != NULL) {\n                    return MINIC_CORE_LOWER_UNSUPPORTED;\n                }\n                memory_output = candidate;\n                memory_index = output_index;\n            } else if (candidate->access == MINIC_INLINE_ASM_OPERAND_WRITE_ONLY &&\n                       core_inline_asm_register_output_constraint(candidate)) {\n                if (register_output != NULL) {\n                    return MINIC_CORE_LOWER_UNSUPPORTED;\n                }\n                register_output = candidate;\n                register_index = output_index;\n            } else {\n                memory_output = NULL;\n                register_output = NULL;\n                break;\n            }\n        }\n        input_expression = minic_c0_program_expression(context->body->program, input->expression);\n        memory_expression = memory_output == NULL\n                                ? NULL\n                                : minic_c0_program_expression(context->body->program,\n                                                              memory_output->expression);\n        register_expression = register_output == NULL\n                                  ? NULL\n                                  : minic_c0_program_expression(context->body->program,\n                                                                register_output->expression);\n        if (memory_output != NULL && register_output != NULL &&\n            input->access == MINIC_INLINE_ASM_OPERAND_READ_ONLY &&\n            core_inline_asm_constraint_is(input, \"r\") && input_expression != NULL &&\n            memory_expression != NULL && register_expression != NULL &&\n            memory_expression->value_category == MINIC_VALUE_LVALUE &&\n            register_expression->kind == MINIC_EXPRESSION_LOCAL &&\n            register_expression->value_category == MINIC_VALUE_LVALUE &&\n            !minic_type_is_const(memory_expression->type) &&\n            !minic_type_is_const(register_expression->type) &&\n            !minic_type_is_volatile(register_expression->type) &&\n            minic_type_unqualified(memory_expression->type, &memory_type) &&\n            minic_type_unqualified(register_expression->type, &output_type) &&\n            core_memory_scalar_type(memory_type) && core_memory_scalar_type(output_type) &&\n            core_scalar_expression_value_type(context->body, input_expression, &input_type) &&\n            minic_type_equal(memory_type, input_type) && minic_type_equal(output_type, memory_type)) {\n            register_local = minic_c0_program_local(\n                context->body->program, register_expression->value.local_id);\n            if (register_local == NULL) {\n                return MINIC_CORE_LOWER_ERROR;\n            }\n            if (!register_local->is_array &&\n                minic_c0_program_local_fixed_register_binding(\n                    context->body->program, register_expression->value.local_id) == NULL &&\n                minic_type_equal(register_local->type, register_expression->type)) {\n                status = lower_expression(context, input->expression, &input_value);\n                if (status != MINIC_CORE_LOWER_OK) {\n                    return status;\n                }\n                status = lower_address(context, memory_output->expression, &memory_address);\n                if (status != MINIC_CORE_LOWER_OK) {\n                    return status;\n                }\n                if (input_value >= context->function->value_count ||\n                    memory_address >= context->function->value_count ||\n                    !minic_type_equal(context->function->values[input_value].type, input_type)) {\n                    return MINIC_CORE_LOWER_ERROR;\n                }\n                if (!minic_core_function_add_opaque_inline_asm(context->function,\n                                                               source->template_text,\n                                                               source->template_length,\n                                                               source->is_volatile,\n                                                               source->has_memory_clobber,\n                                                               &inline_asm_id)) {\n                    return MINIC_CORE_LOWER_ERROR;\n                }\n                (void)memset(&instruction, 0, sizeof(instruction));\n                instruction.kind = MINIC_CORE_INSTRUCTION_MEMORY_READWRITE_SCALAR_INPUT_INLINE_ASM;\n                instruction.span = statement->span;\n                instruction.type = output_type;\n                instruction.result = MINIC_CORE_VALUE_INVALID;\n                instruction.value.memory_readwrite_scalar_input_inline_asm.inline_asm_id =\n                    inline_asm_id;\n                instruction.value.memory_readwrite_scalar_input_inline_asm.memory_address =\n                    memory_address;\n                instruction.value.memory_readwrite_scalar_input_inline_asm.operand = input_value;\n                instruction.value.memory_readwrite_scalar_input_inline_asm.memory_operand_index =\n                    memory_index;\n                instruction.value.memory_readwrite_scalar_input_inline_asm.register_output_operand_index =\n                    register_index;\n                instruction.value.memory_readwrite_scalar_input_inline_asm.scalar_input_operand_index =\n                    2U;\n                if (!minic_core_function_append_value_instruction(\n                        context->function, context->block_id, &instruction, &output_value)) {\n                    return MINIC_CORE_LOWER_ERROR;\n                }\n                status = lower_address(context, register_output->expression, &output_address);\n                if (status != MINIC_CORE_LOWER_OK) {\n                    return status;\n                }\n                (void)memset(&instruction, 0, sizeof(instruction));\n                instruction.kind = MINIC_CORE_INSTRUCTION_STORE;\n                instruction.span = statement->span;\n                instruction.type = minic_type_void();\n                instruction.result = MINIC_CORE_VALUE_INVALID;\n                instruction.value.store.address = output_address;\n                instruction.value.store.stored_value = output_value;\n                instruction.value.store.is_volatile = false;\n                return minic_core_function_append_effect_instruction(\n                           context->function, context->block_id, &instruction)\n                           ? MINIC_CORE_LOWER_OK\n                           : MINIC_CORE_LOWER_ERROR;\n            }\n        }\n    }\n\n    if (source->is_volatile && !source->is_goto && source->template_text != NULL &&\n        source->template_length != 0U && source->outputs != NULL && source->inputs != NULL &&\n        source->output_count == 1U && source->input_count == 1U && source->has_memory_clobber &&\n        source->label_count == 0U && source->register_clobber_count == 0U &&\n        source->clobber_count == 1U) {\n        const MinicInlineAsmOperand *input;\n        const MinicInlineAsmOperand *memory_output;\n        const MinicExpression *input_expression;\n        const MinicExpression *memory_expression;\n        MinicCoreValueId input_value;\n        MinicCoreValueId memory_address;\n        MinicCoreLowerStatus status;\n        MinicType input_type;\n        MinicType memory_type;\n\n        memory_output = &source->outputs[0];\n        input = &source->inputs[0];\n        memory_expression =\n            minic_c0_program_expression(context->body->program, memory_output->expression);\n        input_expression = minic_c0_program_expression(context->body->program, input->expression);\n        if (memory_output->access == MINIC_INLINE_ASM_OPERAND_READ_WRITE &&\n            input->access == MINIC_INLINE_ASM_OPERAND_READ_ONLY &&\n            core_inline_asm_constraint_is(memory_output, \"+A\") &&\n            core_inline_asm_constraint_is(input, \"r\") && memory_expression != NULL &&\n            input_expression != NULL && memory_expression->value_category == MINIC_VALUE_LVALUE &&\n            !minic_type_is_const(memory_expression->type) &&\n            minic_type_unqualified(memory_expression->type, &memory_type) &&\n            core_memory_scalar_type(memory_type) &&\n            core_scalar_expression_value_type(context->body, input_expression, &input_type) &&\n            minic_type_equal(memory_type, input_type)) {\n            status = lower_expression(context, input->expression, &input_value);\n            if (status != MINIC_CORE_LOWER_OK) {\n                return status;\n            }\n            status = lower_address(context, memory_output->expression, &memory_address);\n            if (status != MINIC_CORE_LOWER_OK) {\n                return status;\n            }\n            if (input_value >= context->function->value_count ||\n                memory_address >= context->function->value_count ||\n                !minic_type_equal(context->function->values[input_value].type, input_type)) {\n                return MINIC_CORE_LOWER_ERROR;\n            }\n            if (!minic_core_function_add_opaque_inline_asm(context->function,\n                                                           source->template_text,\n                                                           source->template_length,\n                                                           source->is_volatile,\n                                                           source->has_memory_clobber,\n                                                           &inline_asm_id)) {\n                return MINIC_CORE_LOWER_ERROR;\n            }\n            (void)memset(&instruction, 0, sizeof(instruction));\n            instruction.kind = MINIC_CORE_INSTRUCTION_MEMORY_READWRITE_SCALAR_INPUT_INLINE_ASM;\n            instruction.span = statement->span;\n            instruction.type = minic_type_void();\n            instruction.result = MINIC_CORE_VALUE_INVALID;\n            instruction.value.memory_readwrite_scalar_input_inline_asm.inline_asm_id =\n                inline_asm_id;\n            instruction.value.memory_readwrite_scalar_input_inline_asm.memory_address =\n                memory_address;\n            instruction.value.memory_readwrite_scalar_input_inline_asm.operand = input_value;\n            instruction.value.memory_readwrite_scalar_input_inline_asm.memory_operand_index = 0U;\n            instruction.value.memory_readwrite_scalar_input_inline_asm.register_output_operand_index =\n                SIZE_MAX;\n            instruction.value.memory_readwrite_scalar_input_inline_asm.scalar_input_operand_index =\n                1U;\n            return minic_core_function_append_effect_instruction(\n                       context->function, context->block_id, &instruction)\n                       ? MINIC_CORE_LOWER_OK\n                       : MINIC_CORE_LOWER_ERROR;\n        }\n    }\n\n"""
    texts["lower"] = replace_once(
        texts["lower"], lower_anchor, lower_cases + lower_anchor, "core_lower.c atomic memory asm"
    )

    support_anchor = """static bool core_scalar_input_inline_asm_supported(\n    const MinicCoreFunction *function, const MinicCoreInstruction *instruction) {\n"""
    support_helper = """static bool core_memory_readwrite_scalar_input_inline_asm_supported(\n    const MinicCoreFunction *function, const MinicCoreInstruction *instruction) {\n    const MinicCoreInlineAsm *inline_asm;\n    MinicCoreValueId memory_address;\n    MinicCoreValueId operand;\n    size_t memory_index;\n    size_t register_index;\n    size_t scalar_index;\n    size_t index;\n    bool has_register_output;\n\n    if (function == NULL || instruction == NULL ||\n        instruction->kind != MINIC_CORE_INSTRUCTION_MEMORY_READWRITE_SCALAR_INPUT_INLINE_ASM ||\n        instruction->value.memory_readwrite_scalar_input_inline_asm.inline_asm_id >=\n            function->inline_asm_count) {\n        return false;\n    }\n    memory_address = instruction->value.memory_readwrite_scalar_input_inline_asm.memory_address;\n    operand = instruction->value.memory_readwrite_scalar_input_inline_asm.operand;\n    memory_index = instruction->value.memory_readwrite_scalar_input_inline_asm.memory_operand_index;\n    register_index =\n        instruction->value.memory_readwrite_scalar_input_inline_asm.register_output_operand_index;\n    scalar_index =\n        instruction->value.memory_readwrite_scalar_input_inline_asm.scalar_input_operand_index;\n    has_register_output = register_index != SIZE_MAX;\n    if (memory_address >= function->value_count || operand >= function->value_count ||\n        !minic_type_is_pointer(function->values[memory_address].type) ||\n        (!minic_type_is_integer(function->values[operand].type) &&\n         !minic_type_is_pointer(function->values[operand].type)) ||\n        memory_index > 9U || scalar_index > 9U || memory_index == scalar_index ||\n        (has_register_output &&\n         (register_index > 9U || register_index == memory_index || register_index == scalar_index))) {\n        return false;\n    }\n    if (has_register_output) {\n        if ((!minic_type_is_integer(instruction->type) &&\n             !minic_type_is_pointer(instruction->type)) ||\n            instruction->result == MINIC_CORE_VALUE_INVALID) {\n            return false;\n        }\n    } else if (!minic_type_is_void(instruction->type) ||\n               instruction->result != MINIC_CORE_VALUE_INVALID) {\n        return false;\n    }\n    inline_asm = &function->inline_asms[\n        instruction->value.memory_readwrite_scalar_input_inline_asm.inline_asm_id];\n    if (inline_asm->template_text == NULL || inline_asm->template_length == 0U ||\n        !inline_asm->is_volatile || !inline_asm->has_memory_clobber) {\n        return false;\n    }\n    for (index = 0U; index < inline_asm->template_length; ++index) {\n        size_t operand_index;\n        unsigned char ch;\n\n        if (inline_asm->template_text[index] != '%') {\n            continue;\n        }\n        if (index + 1U >= inline_asm->template_length) {\n            return false;\n        }\n        ch = (unsigned char)inline_asm->template_text[index + 1U];\n        if (ch == '%') {\n            index += 1U;\n            continue;\n        }\n        if (ch < '0' || ch > '9') {\n            return false;\n        }\n        operand_index = (size_t)(ch - '0');\n        if (operand_index != memory_index && operand_index != scalar_index &&\n            (!has_register_output || operand_index != register_index)) {\n            return false;\n        }\n        index += 1U;\n    }\n    return true;\n}\n\n"""
    texts["codegen"] = replace_once(
        texts["codegen"], support_anchor, support_helper + support_anchor, "core_codegen.c support helper"
    )
    texts["codegen"] = replace_once(
        texts["codegen"],
        """    case MINIC_CORE_INSTRUCTION_REGISTER_OUTPUT_INPUT_INLINE_ASM:\n        return core_register_output_input_inline_asm_supported(function, instruction);\n    case MINIC_CORE_INSTRUCTION_SCALAR_INPUT_INLINE_ASM:\n""",
        """    case MINIC_CORE_INSTRUCTION_REGISTER_OUTPUT_INPUT_INLINE_ASM:\n        return core_register_output_input_inline_asm_supported(function, instruction);\n    case MINIC_CORE_INSTRUCTION_MEMORY_READWRITE_SCALAR_INPUT_INLINE_ASM:\n        return core_memory_readwrite_scalar_input_inline_asm_supported(function, instruction);\n    case MINIC_CORE_INSTRUCTION_SCALAR_INPUT_INLINE_ASM:\n""",
        "core_codegen.c supported switch",
    )

    emit_anchor = """static bool emit_scalar_input_inline_asm(\n    FILE *file,\n"""
    emit_helper = """static bool emit_memory_readwrite_scalar_input_inline_asm(\n    FILE *file,\n    const MinicC0Program *program,\n    const MinicCoreFunction *function,\n    const MinicRiscv64CoreFrame *frame,\n    const MinicCoreInstruction *instruction) {\n    const MinicCoreInlineAsm *inline_asm;\n    size_t memory_index;\n    size_t register_index;\n    size_t scalar_index;\n    size_t index;\n    bool has_register_output;\n\n    if (file == NULL || program == NULL || frame == NULL ||\n        !core_memory_readwrite_scalar_input_inline_asm_supported(function, instruction) ||\n        !load_core_value(\n            file,\n            frame,\n            instruction->value.memory_readwrite_scalar_input_inline_asm.memory_address,\n            \"t0\") ||\n        !load_core_value(\n            file, frame, instruction->value.memory_readwrite_scalar_input_inline_asm.operand, \"t2\")) {\n        return false;\n    }\n    memory_index = instruction->value.memory_readwrite_scalar_input_inline_asm.memory_operand_index;\n    register_index =\n        instruction->value.memory_readwrite_scalar_input_inline_asm.register_output_operand_index;\n    scalar_index =\n        instruction->value.memory_readwrite_scalar_input_inline_asm.scalar_input_operand_index;\n    has_register_output = register_index != SIZE_MAX;\n    inline_asm = &function->inline_asms[\n        instruction->value.memory_readwrite_scalar_input_inline_asm.inline_asm_id];\n    if (fprintf(file, \"  \") < 0) {\n        return false;\n    }\n    for (index = 0U; index < inline_asm->template_length; ++index) {\n        size_t operand_index;\n        unsigned char ch;\n\n        if (inline_asm->template_text[index] != '%') {\n            if (fputc((unsigned char)inline_asm->template_text[index], file) == EOF) {\n                return false;\n            }\n            continue;\n        }\n        index += 1U;\n        ch = (unsigned char)inline_asm->template_text[index];\n        if (ch == '%') {\n            if (fputc('%', file) == EOF) {\n                return false;\n            }\n            continue;\n        }\n        if (ch < '0' || ch > '9') {\n            return false;\n        }\n        operand_index = (size_t)(ch - '0');\n        if (operand_index == memory_index) {\n            if (fprintf(file, \"(t0)\") < 0) {\n                return false;\n            }\n        } else if (has_register_output && operand_index == register_index) {\n            if (fprintf(file, \"t1\") < 0) {\n                return false;\n            }\n        } else if (operand_index == scalar_index) {\n            if (fprintf(file, \"t2\") < 0) {\n                return false;\n            }\n        } else {\n            return false;\n        }\n    }\n    if (fputc('\\n', file) == EOF) {\n        return false;\n    }\n    if (!has_register_output) {\n        return true;\n    }\n    if (minic_type_is_integer(instruction->type) &&\n        !minic_riscv64_emit_integer_conversion_for_program(\n            file, program, instruction->type, \"t1\")) {\n        return false;\n    }\n    return store_core_value(file, frame, instruction->result, \"t1\");\n}\n\n"""
    texts["codegen"] = replace_once(
        texts["codegen"], emit_anchor, emit_helper + emit_anchor, "core_codegen.c emit helper"
    )
    texts["codegen"] = replace_once(
        texts["codegen"],
        """    case MINIC_CORE_INSTRUCTION_REGISTER_OUTPUT_INPUT_INLINE_ASM:\n        return emit_register_output_input_inline_asm(file, program, function, frame, instruction);\n    case MINIC_CORE_INSTRUCTION_SCALAR_INPUT_INLINE_ASM:\n""",
        """    case MINIC_CORE_INSTRUCTION_REGISTER_OUTPUT_INPUT_INLINE_ASM:\n        return emit_register_output_input_inline_asm(file, program, function, frame, instruction);\n    case MINIC_CORE_INSTRUCTION_MEMORY_READWRITE_SCALAR_INPUT_INLINE_ASM:\n        return emit_memory_readwrite_scalar_input_inline_asm(\n            file, program, function, frame, instruction);\n    case MINIC_CORE_INSTRUCTION_SCALAR_INPUT_INLINE_ASM:\n""",
        "core_codegen.c emit switch",
    )

    for name, path in FILES.items():
        path.write_text(texts[name])
    print("M52 memory read-write scalar-input inline asm applied")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
